INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Hat ein Mitarbeiter hier immer nur einen Chef?', 2, '[{"text": "Nein", "correct": true, "because": "Mehrere Weisungslinien möglich"}, {"text": "Ja", "correct": false, "because": "Spezialisierte Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal trifft auf diese Organisation zu?', 3, '[{"text": "Fachliche Spezialisierung", "correct": true, "because": "Unterschiedliche Weisungen"}, {"text": "Einheitliche Befehlskette", "correct": false, "because": "Mehrere Linien"}, {"text": "Flache Hierarchie", "correct": false, "because": "Komplexer Aufbau"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet diese Struktur?', 5, '[{"text": "Expertenwissen nutzen", "correct": true, "because": "Fachliche Leitung"}, {"text": "Klare Verantwortung", "correct": false, "because": "Kann unklar sein"}, {"text": "Schnelle Entscheidungen", "correct": false, "because": "Abstimmung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Mehrere Vorgesetzte sind üblich. b) Es gibt keine Hierarchie.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hierarchie bleibt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Koordination in diesem System?', 4, '[{"text": "Fachliche Weisungen", "correct": false, "because": "Kern der Struktur"}, {"text": "Abstimmung zwischen Linien", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Persönliche Präferenzen", "correct": true, "because": "Sachlichkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob hier jeder alles entscheidet?', 2, '[{"text": "Nein", "correct": true, "because": "Weisungen sind spezifisch"}, {"text": "Ja", "correct": false, "because": "Fachbereiche getrennt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderung trifft hier oft zu?', 3, '[{"text": "Konflikte zwischen Vorgesetzten", "correct": true, "because": "Unterschiedliche Prioritäten"}, {"text": "Zu wenig Verantwortung", "correct": false, "because": "Eher zu viel"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Abstimmung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente prägen dieses System?', 5, '[{"text": "Fachliche Leitung", "correct": true, "because": "Spezialisierte Weisungen"}, {"text": "Multiple Berichtslinien", "correct": true, "because": "Mehrere Chefs"}, {"text": "Flache Struktur", "correct": false, "because": "Komplexer Aufbau"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Mehrliniensystem ist für Experten. b) Es ist immer chaotisch. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Chaos nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Koordination", "correct": false, "because": "Vermeidet Konflikte"}, {"text": "Klar definierte Rollen", "correct": false, "because": "Reduziert Verwirrung"}, {"text": "Einheitliche Befehle", "correct": true, "because": "Mehrere Linien üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das System für kleine Teams geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Komplexität oft überflüssig"}, {"text": "Ja", "correct": false, "because": "Besser für größere Strukturen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte fördern den Erfolg hier?', 4, '[{"text": "Klare Kommunikation", "correct": true, "because": "Verhindert Missverständnisse"}, {"text": "Abgestimmte Prioritäten", "correct": true, "because": "Reduziert Konflikte"}, {"text": "Einzelentscheidungen", "correct": false, "because": "Abstimmung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hier alles doppelt geprüft wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Koordination"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch doppelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich in diesem System?', 3, '[{"text": "Abstimmung zwischen Linien", "correct": true, "because": "Vermeidet Chaos"}, {"text": "Schnelle Befehle", "correct": false, "because": "Koordination nötig"}, {"text": "Einzelinitiative", "correct": false, "because": "Teamarbeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fachbereiche haben eigene Chefs. b) Es gibt keine Koordination.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Koordination essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile könnten auftreten?', 5, '[{"text": "Unklare Prioritäten", "correct": true, "because": "Mehrere Weisungen"}, {"text": "Langsame Entscheidungen", "correct": true, "because": "Abstimmung nötig"}, {"text": "Zu viel Autonomie", "correct": false, "because": "Eher zu wenig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger  unwichtig?', 3, '[{"text": "Fachliche Expertise", "correct": false, "because": "Kern der Struktur"}, {"text": "Koordination", "correct": false, "because": "Schlüssel zum Erfolg"}, {"text": "Einheitliche Linie", "correct": true, "because": "Nicht zwingend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das System immer effizient?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Koordination"}, {"text": "Ja", "correct": false, "because": "Komplexität kann bremsen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob hier jeder doppelt berichten muss?', 2, '[{"text": "Ja", "correct": true, "because": "Mehrere Linien möglich"}, {"text": "Nein", "correct": false, "because": "Abhängig von Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Kommunikation hier?', 4, '[{"text": "Entscheidend", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Nebensächlich", "correct": false, "because": "Koordination nötig"}, {"text": "Optional", "correct": false, "because": "Erfolgsfaktor"}]');
